3	namespace App\Services\Cache;
4	
5	use App\Models\Core\MediaVariant;
6	use App\Models\Core\Professional\BrandPartnerLink;
7	use App\Models\Core\Professional\Professional;
8	use App\Models\Core\Site\Block;
9	use App\Models\Core\Site\Site;
10	use App\Models\Core\Site\SiteSubdomainAlias;
11	use App\Models\Views\PublicSitePayload;
12	use Illuminate\Support\Facades\Cache;
13	use Illuminate\Support\Facades\Log;
14	use Illuminate\Support\Facades\Storage;
15	
16	// V2: Public site payload caching with single-flight locking (prevents thundering herd). Handles 95% of traffic. Simplified in V2 — no more product payload caching.
17	class SiteCacheService
18	{
19	    private const MISS_SENTINEL = '__MISS__';
20	
21	    // Public site payload TTL (15 min). Stored as int so we can jitter ±20% on
22	    // each write — without it, a deploy fills 1,500 sites' caches in one window
23	    // and they all expire in the same instant 15 min later (thundering-herd on
24	    // expiry). Jitter spreads the expiry burst across a ~6-minute window.
25	    private const PAYLOAD_TTL_SECONDS = 900;
26	
27	    /** @var array<string, array<string, string|null>|null> */
28	    private array $brandPartnerEnrichmentCache = [];
29	
30	    public function __construct(private readonly CacheLockService $cacheLock) {}
31	
32	    /**
33	     * Returns PAYLOAD_TTL_SECONDS with ±20% jitter applied.
34	     *
35	     * Mirrors CacheLockService::writeWithJitter's distribution so payload-cache
36	     * writes (which use raw Cache::put inside our manual single-flight) get the
37	     * same expiry-spreading behaviour as rememberLocked-managed entries.
38	     */
39	    private function jitteredPayloadTtl(): int
40	    {
41	        return (int) round(self::PAYLOAD_TTL_SECONDS * (0.8 + mt_rand(0, 4000) / 10000.0));
42	    }
43	
44	    /**
45	     * Get public site payload (MOST CRITICAL - 95% of traffic)
46	     *
47	     * IMPORTANT: This must match the PublicSiteController response shape exactly.
48	     */
49	    public function getPublicSitePayload(string $subdomain): ?array
50	    {
51	        $subdomain = strtolower($subdomain);
52	
53	        $key = CacheKeyGenerator::publicSitePayload($subdomain);
54	        $cached = Cache::get($key);
55	
56	        if ($cached === self::MISS_SENTINEL) {
57	            return null;
58	        }
59	        if (is_array($cached)) {
60	            // Backward-compatible cache healing for payload shape changes.
61	            // Older cache entries may not include `services`.
62	            if (array_key_exists('services', $cached)) {
63	                $cached = $this->ensureBlockCollections($cached);
64	                $cached = $this->ensureProfessionalType(
65	                    $cached,
66	                    (string) data_get($cached, 'professional.id', '')
67	                );
68	                $cached = $this->safeWithStorePayload(
69	                    $cached,
70	                    (string) data_get($cached, 'professional.id', ''),
71	                    $subdomain
72	                );
73	
74	                if (! array_key_exists('legal', $cached)) {
75	                    $cached['legal'] = null;
76	                }
77	
78	                // Always resolve image variant paths to URLs (handles pre-URL-resolution cache entries)
79	                $site = $cached['site'] ?? null;
80	                if (is_array($site)) {
81	                    $professionalId = (string) data_get($cached, 'professional.id', '');
82	                    $cached['site'] = $this->safeHydrateSitePayload(
83	                        $site,
84	                        $professionalId,
85	                        '',
86	                        $subdomain
87	                    );
88	                }
89	
90	                Cache::put($key, $cached, $this->jitteredPayloadTtl());
91	
92	                return $cached;
93	            }
94	            Cache::forget($key);
95	        }
96	
97	        // Cache miss — acquire a per-subdomain fill lock so only one process rebuilds
98	        // the payload from the DB view while concurrent requests wait (single-flight).
99	        $fillLock = Cache::lock('site:fill:'.$subdomain, 10);
100	
101	        try {
102	            // Block up to 5 s for the lock; raises LockTimeoutException if it can't.
103	            $fillLock->block(5);
104	        } catch (\Illuminate\Contracts\Cache\LockTimeoutException) {
105	            // Another process is (or was) filling the cache.
106	            // Return whatever is now in cache, or null if it's still a miss.
107	            $warm = Cache::get($key);
108	            if ($warm === self::MISS_SENTINEL) {
109	                return null;
110	            }
111	
112	            return is_array($warm) ? $warm : null;
113	        }
114	
115	        try {
116	            // Double-check: the lock winner may have filled the cache while we waited.
117	            $rechecked = Cache::get($key);
118	            if ($rechecked === self::MISS_SENTINEL) {
119	                return null;
120	            }
121	            if (is_array($rechecked) && array_key_exists('services', $rechecked)) {
122	                return $rechecked;
123	            }
124	
125	            $row = PublicSitePayload::query()
126	                ->whereRaw('lower(subdomain) = ?', [$subdomain])
127	                ->first();
128	
129	            // View only contains published sites; if not found, treat as 404.
130	            if (! $row) {
131	                // Negative-cache briefly to reduce DB load from bot scans.
132	                Cache::put($key, self::MISS_SENTINEL, now()->addSeconds(30));
133	
134	                return null;
135	            }
136	
137	            $payload = $row->payload ?? [];
138	
139	            // The view's COALESCE guarantees services is always a jsonb array,
140	            // so a missing key is the only thing we have to defend against.
141	            $services = $payload['services'] ?? [];
142	
143	            $site = $payload['site'] ?? null;
144	            if (is_array($site)) {
145	                $site = $this->safeHydrateSitePayload(
146	                    $site,
147	                    (string) ($row->professional_id ?? ''),
148	                    (string) ($row->site_id ?? ''),
149	                    $subdomain
150	                );
151	            }
152	
153	            // Must match the controller response shape exactly.
154	            $links = is_array($payload['links'] ?? null) ? array_values($payload['links']) : [];
155	            $sections = is_array($payload['sections'] ?? null) ? array_values($payload['sections']) : [];
156	            $existingBlocks = is_array($payload['blocks'] ?? null) ? array_values($payload['blocks']) : [];
157	
158	            $data = [
159	                'published' => true,
160	                'site' => $site,
161	                'professional' => $payload['professional'] ?? null,
162	                'theme' => $payload['theme'] ?? null,
163	                'services' => $services,
164	                'links' => $links,
165	                'sections' => $sections,
166	                'blocks' => $this->buildCombinedBlocksPayload($links, $sections, $existingBlocks),
167	                'legal' => $payload['legal'] ?? null,
168	                // Preserve the store sub-object from the source payload so that
169	                // withStorePayload() below can lift selected_products + commission
170	                // settings out of payload.store. Without this, the rebuilt $data
171	                // has no 'store' key and withStorePayload falls through to empty
172	                // defaults — the front-end would see no featured products even
173	                // though the view row contains them.
174	                'store' => $payload['store'] ?? null,
175	            ];
176	            $data = $this->ensureProfessionalType($data, (string) ($row->professional_id ?? ''));
177	            $data = $this->safeWithStorePayload($data, (string) ($row->professional_id ?? ''), $subdomain);
178	            $data = $this->safeApplyBrandImageFallbacks($data, $subdomain);
179	
180	            Cache::put($key, $data, $this->jitteredPayloadTtl());
181	
182	            return $data;
183	        } finally {
184	            $fillLock->release();
185	        }
186	    }
187	
188	    /**
189	     * @param  array<string, mixed>  $payload
190	     * @return array<string, mixed>
191	     */
192	    private function applyBrandImageFallbacks(array $payload): array
193	    {
194	        $professional = $payload['professional'] ?? null;
195	        if (! is_array($professional) || ($professional['professional_type'] ?? null) === 'brand') {
196	            return $payload;
197	        }
198	
199	        $affiliateId = (string) ($professional['id'] ?? '');
200	        if (empty($affiliateId)) {
201	            return $payload;
202	        }
203	
204	        // JSON column is affiliate-controlled; use it only as a hint for which brand is configured.
205	        $brandPartner = $payload['site']['settings']['brand_partner'] ?? null;
206	        if (! is_array($brandPartner) || empty($brandPartner['professional_id'])) {
207	            return $payload;
208	        }
209	
210	        $claimedBrandId = (string) $brandPartner['professional_id'];
211	
212	        // BrandPartnerLink is the consent record — verify before using any brand data.
213	        $link = BrandPartnerLink::where('affiliate_professional_id', $affiliateId)
214	            ->where('brand_professional_id', $claimedBrandId)
215	            ->first();
216	
217	        if (! $link) {
218	            Log::warning('Brand-partner enrichment skipped: no verified link in consent table.', [
219	                'affiliate_id' => $affiliateId,
220	                'brand_id' => $claimedBrandId,
221	            ]);
222	
223	            return $payload;
224	        }
225	
226	        // Resolve brand_id from the verified link record, never from the mutable JSON.
227	        $brandId = (string) $link->brand_professional_id;
228	        $brandSite = Site::query()
229	            ->where('professional_id', $brandId)
230	            ->first();
231	
232	        if (! $brandSite) {
233	            return $payload;
234	        }
235	
236	        // Brand placeholders now live in site_media (pool=design, purpose=placeholder).
237	        // The service resolves variant URLs; we project them to { url, alt_text }
238	        // to match the new Hydrogen brand-design response shape.
239	        $designMedia = app(\App\Services\Media\BrandDesignMediaService::class)
240	            ->listDesignMedia((string) $brandSite->id);
241	
242	        if (empty($designMedia['placeholders'])) {
243	            return $payload;
244	        }
245	
246	        $placeholderImages = array_map(
247	            fn (array $p) => [
248	                'url' => $p['url'],
249	                'alt_text' => $p['alt_text'],
250	            ],
251	            $designMedia['placeholders']
252	        );
253	
254	        $imageKeys = ['gallery', 'content_images'];
255	
256	        foreach ($imageKeys as $key) {
257	            if (! isset($payload['site'][$key]) || ! is_array($payload['site'][$key])) {
258	                continue;
259	            }
260	
261	            if (empty($payload['site'][$key])) {
262	                $payload['site'][$key] = $placeholderImages;
263	            }
264	        }
265	
266	        return $payload;
267	    }
268	
269	    /**
270	     * @param  array<string, mixed>  $site
271	     * @return array<string, mixed>
272	     */
273	    private function safeHydrateSitePayload(array $site, string $professionalId, string $siteId, string $subdomain): array
274	    {
275	        try {
276	            $site = $this->hydrateSiteWithBrandTypography($site, $professionalId);
277	            $site = $this->resolveImageVariantUrlsInSite($site, $siteId);
278	
279	            return $this->enrichSiteWithBrandPartnerRadius($site);
280	        } catch (\Throwable $e) {
281	            Log::warning('Public site payload hydration failed; returning base site payload.', [
282	                'subdomain' => $subdomain,
283	                'professional_id' => $professionalId,
284	                'site_id' => $siteId,
285	                'error' => $e->getMessage(),
286	            ]);
287	
288	            return $site;
289	        }
290	    }
291	
292	    /**
293	     * @param  array<string, mixed>  $payload
294	     * @return array<string, mixed>
295	     */
296	    private function safeWithStorePayload(array $payload, string $professionalId, string $subdomain): array
297	    {
298	        try {
299	            return $this->withStorePayload($payload, $professionalId);
300	        } catch (\Throwable $e) {
301	            Log::warning('Public site store payload build failed; returning payload without refreshed store data.', [
302	                'subdomain' => $subdomain,
303	                'professional_id' => $professionalId,
304	                'error' => $e->getMessage(),
305	            ]);
306	
307	            return $payload;
308	        }
309	    }
310	
311	    /**
312	     * @param  array<string, mixed>  $payload
313	     * @return array<string, mixed>
314	     */
315	    private function safeApplyBrandImageFallbacks(array $payload, string $subdomain): array
316	    {
317	        try {
318	            return $this->applyBrandImageFallbacks($payload);
319	        } catch (\Throwable $e) {
320	            Log::warning('Brand image fallback enrichment failed; returning payload unchanged.', [
321	                'subdomain' => $subdomain,
322	                'professional_id' => (string) data_get($payload, 'professional.id', ''),
323	                'error' => $e->getMessage(),
324	            ]);
325	
326	            return $payload;
327	        }
328	    }
329	
330	    /**
331	     * @param  array<string, mixed>  $site
332	     * @return array<string, mixed>
333	     */
334	    public function hydrateSiteWithBrandTypography(array $site, string $brandProfessionalId): array
