546	    /**
547	     * @param  array<int, mixed>  $links
548	     * @param  array<int, mixed>  $sections
549	     * @param  array<int, mixed>  $existingBlocks
550	     * @return array<int, array<string, mixed>>
551	     */
552	    private function buildCombinedBlocksPayload(array $links, array $sections, array $existingBlocks = []): array
553	    {
554	        if ($links === [] && $sections === []) {
555	            return array_values(array_filter($existingBlocks, fn ($block): bool => is_array($block)));
556	        }
557	
558	        $normalizedLinks = array_map(function ($block): array {
559	            $data = is_array($block) ? $block : [];
560	            $data['block_group'] = 'links';
561	
562	            return $data;
563	        }, $links);
564	
565	        $normalizedSections = array_map(function ($block): array {
566	            $data = is_array($block) ? $block : [];
567	            $data['block_group'] = 'sections';
568	
569	            return $data;
570	        }, $sections);
571	
572	        $combined = array_merge($normalizedLinks, $normalizedSections);
573	
574	        usort($combined, function (array $a, array $b): int {
575	            $aSort = (int) ($a['sort_order'] ?? PHP_INT_MAX);
576	            $bSort = (int) ($b['sort_order'] ?? PHP_INT_MAX);
577	            if ($aSort !== $bSort) {
578	                return $aSort <=> $bSort;
579	            }
580	
581	            $aId = (string) ($a['id'] ?? '');
582	            $bId = (string) ($b['id'] ?? '');
583	
584	            return $aId <=> $bId;
585	        });
586	
587	        return array_values($combined);
588	    }
