649	    /**
650	     * Resolve image variant paths to public URLs in the site payload.
651	     * The view returns storage paths; we need full URLs for the frontend.
652	     * Also resolves video variant/stream/poster paths in gallery_videos and content_videos.
653	     *
654	     * @param  array<string, mixed>  $site
655	     * @return array<string, mixed>
656	     */
657	    private function resolveImageVariantUrlsInSite(array $site, string $siteId): array
658	    {
659	        // --- Collect all media IDs (images + videos) in one pass ---
660	        $allMediaIds = [];
661	        foreach (['gallery', 'content_images', 'gallery_videos', 'content_videos'] as $key) {
662	            foreach ($site[$key] ?? [] as $item) {
663	                if (is_array($item) && ! empty($item['id'])) {
664	                    $allMediaIds[] = $item['id'];
665	                }
666	            }
667	        }
668	
669	        // Single query: one DB round-trip for all variant rows across all media types.
670	        // Index as: media_id → artifact_type → variant_key → URL
671	        $mvByMedia = [];
672	        if ($allMediaIds !== []) {
673	            $allVariants = MediaVariant::query()
674	                ->whereIn('media_id', array_unique($allMediaIds))
675	                ->get();
676	
677	            foreach ($allVariants as $mv) {
678	                $mvByMedia[$mv->media_id][$mv->artifact_type][$mv->variant_key] = $mv->url;
679	            }
680	        }
681	
682	        // --- Images: resolve variant URLs ---
683	        foreach (['gallery', 'content_images'] as $key) {
684	            $items = $site[$key] ?? [];
685	            if (! is_array($items)) {
686	                continue;
687	            }
688	            foreach ($items as $i => $item) {
689	                if (! is_array($item) || empty($item['id'])) {
690	                    continue;
691	                }
692	                $mediaId = $item['id'];
693	                $pathVariants = $item['variants'] ?? [];
694	                if (! is_array($pathVariants)) {
695	                    continue;
696	                }
697	                $urlVariants = [];
698	                foreach ($pathVariants as $variantKey => $path) {
699	                    $url = $mvByMedia[$mediaId]['webp'][$variantKey] ?? null;
700	                    if ($url !== null) {
701	                        $urlVariants[$variantKey] = $url;
702	                    }
703	                }
704	                $site[$key][$i]['variants'] = $urlVariants;
705	            }
706	
707	            usort($site[$key], function ($a, $b) {
708	                $aSort = is_array($a) ? (int) ($a['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
709	                $bSort = is_array($b) ? (int) ($b['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
710	                if ($aSort !== $bSort) {
711	                    return $aSort <=> $bSort;
712	                }
713	                $aId = is_array($a) ? (string) ($a['id'] ?? '') : '';
714	                $bId = is_array($b) ? (string) ($b['id'] ?? '') : '';
715	
716	                return $aId <=> $bId;
717	            });
718	        }
719	
720	        // --- Videos: resolve variant/stream/poster URLs ---
721	        foreach (['gallery_videos', 'content_videos'] as $key) {
722	            $items = $site[$key] ?? [];
723	            if (! is_array($items)) {
724	                continue;
725	            }
726	            foreach ($items as $i => $item) {
727	                if (! is_array($item) || empty($item['id'])) {
728	                    continue;
729	                }
730	                $mediaId = $item['id'];
731	                $byType = $mvByMedia[$mediaId] ?? [];
732	
733	                $site[$key][$i]['variants'] = $byType['mp4'] ?? [];
734	                $site[$key][$i]['streams'] = $byType['hls_playlist'] ?? [];
735	                $site[$key][$i]['poster'] = ($byType['poster']['poster'] ?? null);
736	            }
737	
738	            usort($site[$key], function ($a, $b) {
739	                $aSort = is_array($a) ? (int) ($a['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
740	                $bSort = is_array($b) ? (int) ($b['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
741	                if ($aSort !== $bSort) {
742	                    return $aSort <=> $bSort;
743	                }
744	                $aId = is_array($a) ? (string) ($a['id'] ?? '') : '';
745	                $bId = is_array($b) ? (string) ($b['id'] ?? '') : '';
746	
747	                return $aId <=> $bId;
748	            });
749	        }
750	
751	        // Ensure video keys always exist even when there are no videos (backward-compat).
752	        $site['gallery_videos'] = $site['gallery_videos'] ?? [];
753	        $site['content_videos'] = $site['content_videos'] ?? [];
754	
755	        // --- Document: resolve preview_url from storage path to full CDN URL ---
756	        if (isset($site['document']) && is_array($site['document']) && ! empty($site['document']['preview_url'])) {
757	            $rawPath = (string) $site['document']['preview_url'];
758	            $site['document']['preview_url'] = Storage::disk(config('partna.media_disk'))->url($rawPath);
759	        }
760	
761	        return $site;
762	    }
