788	    /**
789	     * Invalidate all cache keys for a site
790	     */
791	    public function invalidateSite(Site $site): void
792	    {
793	        $professionalId = (string) ($site->professional_id ?? '');
794	
795	        $keys = [
796	            CacheKeyGenerator::publicSitePayload($site->subdomain),
797	            ...self::bustWithStale(CacheKeyGenerator::siteBlocks($site->id, 'links')),
798	            ...self::bustWithStale(CacheKeyGenerator::siteBlocks($site->id, 'sections')),
799	            CacheKeyGenerator::siteImages($site->id),
800	        ];
801	
802	        // CACHE-1: every (pool, media_type) variant of /api/images. The polling
803	        // path (?ids[]) uses unbounded fingerprint keys and relies on its own 5s
804	        // TTL — not enumerated here.
805	        foreach (CacheKeyGenerator::siteImagesViewVariants() as [$pool, $mediaType]) {
806	            $variantKey = CacheKeyGenerator::siteImagesView($site->id, $pool, $mediaType);
807	            $keys[] = $variantKey;
808	            $keys[] = $variantKey.':stale';
809	        }
810	
811	        // The auth-path Professional model cache (AUTH-1) holds the site relation
812	        // preloaded — site writes must bust it or the next 60s of authenticated
813	        // requests would see a stale subdomain / settings on $pro->site.
814	        if ($professionalId !== '') {
815	            $modelKey = CacheKeyGenerator::professionalModel($professionalId);
816	            $keys[] = $modelKey;
817	            $keys[] = $modelKey.':stale';
818	        }
819	
820	        // If subdomain changed, kill the OLD cache key too.
821	        // This is critical so old URLs redirect (via alias) instead of returning cached payload.
822	        if ($site->wasChanged('subdomain')) {
823	            $old = strtolower((string) $site->getOriginal('subdomain'));
824	            if ($old !== '') {
825	                $keys[] = CacheKeyGenerator::publicSitePayload($old);
826	            }
827	        }
828	
829	        // Invalidate all alias cache keys (your Site model has no aliases() relation)
830	        $aliasSubdomains = SiteSubdomainAlias::query()
831	            ->where('site_id', $site->id)
832	            ->pluck('subdomain')
833	            ->all();
834	
835	        foreach ($aliasSubdomains as $aliasSubdomain) {
836	            $keys[] = CacheKeyGenerator::publicSitePayload(strtolower($aliasSubdomain));
837	        }
838	
839	        if ($professionalId !== '') {
840	            $connectedProfessionalIds = BrandPartnerLink::query()
841	                ->where('brand_professional_id', $professionalId)
842	                ->pluck('affiliate_professional_id')
843	                ->all();
844	
845	            $connectedSubdomains = Site::query()
846	                ->whereIn('professional_id', $connectedProfessionalIds)
847	                ->pluck('subdomain')
848	                ->filter(fn ($subdomain): bool => is_string($subdomain) && trim($subdomain) !== '')
849	                ->map(fn ($subdomain): string => strtolower((string) $subdomain))
850	                ->all();
851	
852	            foreach ($connectedSubdomains as $connectedSubdomain) {
853	                $keys[] = CacheKeyGenerator::publicSitePayload($connectedSubdomain);
854	            }
855	        }
856	
857	        Cache::deleteMultiple(array_values(array_unique($keys)));
858	    }
