12	// V2: Multi-lookup professional caching (by ID, handle, auth_user_id). Defensive validation prevents returning stale data after handle/auth changes.
13	class ProfessionalCacheService
14	{
15	    public function __construct(private CacheLockService $cacheLock) {}
16	
17	    /* ---------------------------
18	     |  ID mapping (fast lookups)
19	     * --------------------------*/
20	
21	    public function getIdByAuthId(string $authUserId): ?string
22	    {
23	        // Auth-path cache hit on every authenticated request — single-flight is critical.
24	        // Short null-TTL (30s) so a freshly-signed-up user doesn't see "not found" for 30 minutes.
25	        return $this->cacheLock->rememberLockedNullable(
26	            CacheKeyGenerator::professionalIdByAuthId($authUserId),
27	            now()->addMinutes(30),
28	            fn () => Professional::query()
29	                ->where('auth_user_id', $authUserId)
30	                ->value('id'),
31	            nullTtl: now()->addSeconds(30),
32	        );
33	    }
34	
35	    public function getIdByHandle(string $handle): ?string
36	    {
37	        $handleLc = strtolower($handle);
38	
39	        return $this->cacheLock->rememberLockedNullable(
40	            CacheKeyGenerator::professionalIdByHandle($handleLc),
41	            now()->addHour(),
42	            fn () => Professional::query()
43	                ->where('handle_lc', $handleLc)
44	                ->value('id'),
45	            nullTtl: now()->addSeconds(30),
46	        );
47	    }
48	
49	    /* ---------------------------
50	     |  Payload (array pattern)
51	     * --------------------------*/
52	
53	    public function getPayloadById(string $id): ?array
54	    {
55	        return $this->cacheLock->rememberLockedNullable(
56	            CacheKeyGenerator::professionalPayloadById($id),
57	            now()->addHour(),
58	            function () use ($id) {
59	                $pro = Professional::query()->with('site')->find($id);
60	
61	                return $pro ? $this->toPayload($pro) : null;
62	            },
63	            nullTtl: now()->addSeconds(30),
64	        );
65	    }
66	
67	    public function getPayloadByHandle(string $handle): ?array
68	    {
69	        $handleLc = strtolower($handle);
70	        $id = $this->getIdByHandle($handleLc);
71	
72	        return $id ? $this->getPayloadById($id) : null;
73	    }
74	
75	    public function getPayloadByAuthId(string $authUserId): ?array
76	    {
77	        $id = $this->getIdByAuthId($authUserId);
78	
79	        return $id ? $this->getPayloadById($id) : null;
80	    }
