82	    private function toPayload(Professional $pro): array
83	    {
84	        // NOTE: your Professional model has protected $with = ['site'];
85	        $site = $pro->site;
86	        $siteSettings = [];
87	        if ($site) {
88	            $siteSettings = is_array($site->settings) ? $site->settings : [];
89	        }
90	
91	        return [
92	            'professional' => [
93	                'id' => $pro->id,
94	                'auth_user_id' => $pro->auth_user_id,
95	                'handle' => $pro->handle,
96	                'handle_lc' => $pro->handle_lc,
97	                'display_name' => $pro->display_name,
98	                'bio' => $pro->bio,
99	                'country_code' => $pro->country_code,
100	                'timezone' => $pro->timezone,
101	                'professional_type' => $pro->professional_type,
102	                'status' => $pro->status,
103	                'onboarding_step' => $pro->onboarding_step,
104	                'qr_slug' => $pro->qr_slug,
105	
106	                'public_contact_number' => $pro->public_contact_number,
107	                'public_contact_email' => $pro->public_contact_email,
108	
109	                'location_street_address' => $pro->location_street_address,
110	                'location_city' => $pro->location_city,
111	                'location_state' => $pro->location_state,
112	                'location_postcode' => $pro->location_postcode,
113	                'location_country' => $pro->location_country,
114	
115	                'created_at' => optional($pro->created_at)->toIso8601String(),
116	                'updated_at' => optional($pro->updated_at)->toIso8601String(),
117	            ],
118	            'site' => $site ? [
119	                'id' => $site->id,
120	                'subdomain' => $site->subdomain,
121	                'is_published' => (bool) $site->is_published,
122	                'settings' => $siteSettings,
123	            ] : null,
124	        ];
125	    }
