149	    public function getByAuthId(string $authUserId): ?Professional
150	    {
151	        $id = $this->getIdByAuthId($authUserId);
152	        if (! $id) {
153	            return null;
154	        }
155	
156	        // Cache the hydrated model for 60s with SWR + jitter. Eager-loading site +
157	        // squareIntegration here makes them effectively free for every authenticated
158	        // request — they ride along inside the cached model, paid once per 60s window.
159	        $professional = $this->cacheLock->rememberLocked(
160	            CacheKeyGenerator::professionalModel($id),
161	            60,
162	            fn () => Professional::query()->with(['site', 'squareIntegration'])->find($id),
163	        );
164	        if (! $professional) {
165	            return null;
166	        }
167	
168	        // Defensive guard: if cache is stale/corrupt, never return another user's profile.
169	        if ((string) $professional->auth_user_id !== $authUserId) {
170	            $authIdKey = CacheKeyGenerator::professionalIdByAuthId($authUserId);
171	            $modelKey = CacheKeyGenerator::professionalModel($id);
172	            Cache::forget($authIdKey);
173	            Cache::forget($modelKey);
174	            Cache::forget($modelKey.':stale');
