304	    public function invalidateProfessional(Professional $professional): void
305	    {
306	        $handleLc = strtolower($professional->handle);
307	
308	        $modelKey = CacheKeyGenerator::professionalModel($professional->id);
309	
310	        $keys = [
311	            CacheKeyGenerator::professionalPayloadById($professional->id),
312	            CacheKeyGenerator::professionalPayloadByHandle($handleLc),
313	            CacheKeyGenerator::professionalPayloadByAuthId($professional->auth_user_id),
314	
315	            CacheKeyGenerator::professionalIdByHandle($handleLc),
316	            CacheKeyGenerator::professionalIdByAuthId($professional->auth_user_id),
317	
318	            // Auth-path hydrated-model cache (60 s SWR). Both the primary key and
319	            // the `:stale` last-good copy must die here, otherwise stale-while-
320	            // revalidate would let writes appear cached for up to 10 minutes.
321	            $modelKey,
322	            $modelKey.':stale',
323	
324	            CacheKeyGenerator::professionalServices($professional->id),
325	            CacheKeyGenerator::professionalDashboardServices($professional->id),
326	            CacheKeyGenerator::customerCount($professional->id),
327	
328	            // brand-partner-status (CACHE-5): keyed by brand professional id, so
329	            // when *this* professional's display_name changes, every affiliate
330	            // pointing at this brand re-reads it. Cheap to bust unconditionally.
331	            CacheKeyGenerator::brandPartnerStatus($professional->id),
332	        ];
333	
334	        if ($professional->wasChanged('handle')) {
335	            $old = strtolower((string) $professional->getOriginal('handle'));
336	            if ($old !== '') {
337	                $keys[] = CacheKeyGenerator::professionalPayloadByHandle($old);
338	                $keys[] = CacheKeyGenerator::professionalIdByHandle($old);
339	            }
340	        }
341	
342	        if ($professional->wasChanged('auth_user_id')) {
343	            $old = (string) $professional->getOriginal('auth_user_id');
344	            if ($old !== '') {
345	                $keys[] = CacheKeyGenerator::professionalPayloadByAuthId($old);
346	                $keys[] = CacheKeyGenerator::professionalIdByAuthId($old);
347	            }
348	        }
349	
350	        Cache::deleteMultiple(array_values(array_unique($keys)));
351	
352	        // Also invalidate site cache (public payload includes professional fields)
353	        if ($professional->site) {
354	            app(SiteCacheService::class)->invalidateSite($professional->site);
355	        }
356	    }
357	}
