14	// Backs the affiliate-product-block Shopify admin UI extension.
15	// Returns 30-day affiliate sales for a single product: totals, variant rollup,
16	// recent sales, and the Partna active state.
17	//
18	// Cached per (brand, product) for 5 minutes — the variant rollup query is
19	// non-trivial and the data only refreshes on Shopify orders/paid webhooks.
20	class EmbeddedProductAnalyticsController extends ApiController
21	{
22	    public function __construct(
23	        private readonly BrandCatalogService $catalog,
24	    ) {}
25	
26	    /**
27	     * @return JsonResponse {
28	     *                      product_id: string,
29	     *                      active: bool|null,
30	     *                      currency_code: string,
31	     *                      period_days: int,
32	     *                      totals: { units: int, revenue_cents: int, commission_cents: int, avg_commission_rate: float },
33	     *                      variants: Array<{ variant_id, variant_title, units, revenue_cents }>,
34	     *                      recent_sales: Array<{ affiliate_name, quantity, revenue_cents, commission_cents, occurred_at }>,
35	     *                      }
36	     */
37	    public function show(Request $request, string $shopifyProductId): JsonResponse
38	    {
39	        $professionalId = (string) $request->attributes->get('embedded_professional_id');
40	        $productId = (string) preg_replace('#^gid://shopify/Product/#', '', $shopifyProductId);
41	
42	        $cacheKey = "embedded:product-analytics:{$professionalId}:{$productId}";
43	
44	        return Cache::remember($cacheKey, now()->addMinutes(5), function () use ($professionalId, $productId) {
45	            return $this->success($this->build($professionalId, $productId));
46	        });
47	    }
48	
49	    /**
50	     * @return array<string, mixed>
51	     */
52	    private function build(string $professionalId, string $productId): array
53	    {
54	        $thirtyDaysAgo = now()->subDays(30);
55	
56	        // Phase 4+: read from commerce.order_items (denormalized per-line) joined to commerce.orders
57	        // for status filtering. Excludes stub/cancelled/voided/refunded so they don't pollute totals.
58	        // The webhook job pre-computes per-line commission_cents/commission_rate into the line_items
59	        // JSONB; the order_items_diff trigger mirrors them into this table.
60	        $rows = DB::table('commerce.order_items as oi')
61	            ->join('commerce.orders as o', 'o.id', '=', 'oi.order_id')
62	            ->leftJoin('core.professionals as p', 'p.id', '=', 'oi.affiliate_professional_id')
63	            ->where('oi.brand_professional_id', $professionalId)
64	            ->where('oi.shopify_product_id', $productId)
65	            ->where('oi.occurred_at', '>=', $thirtyDaysAgo)
66	            ->whereNotIn('o.status', Order::EXCLUDED_FROM_AGGREGATES)
67	            ->orderByDesc('oi.occurred_at')
68	            ->get([
69	                'oi.shopify_variant_id',
70	                'oi.title',
71	                'oi.quantity',
72	                'oi.line_total_cents',
73	                'oi.commission_cents',
74	                'oi.commission_rate',
75	                'oi.currency_code',
76	                'oi.occurred_at',
77	                'oi.affiliate_professional_id',
78	                'p.display_name as affiliate_name',
79	            ]);
80	
81	        $totalUnits = 0;
82	        $totalRevenueCents = 0;
83	        $totalCommissionCents = 0;
84	        $weightedRateSum = 0.0;
85	        $rateWeight = 0;
86	        $currency = 'AUD';
87	
88	        // variant_id => { variant_id, variant_title, units, revenue_cents }
89	        $variants = [];
90	
91	        foreach ($rows as $row) {
92	            $qty = (int) $row->quantity;
93	            $revenueCents = (int) $row->line_total_cents;
94	            $commissionCents = (int) $row->commission_cents;
95	
96	            $totalUnits += $qty;
97	            $totalRevenueCents += $revenueCents;
98	            $totalCommissionCents += $commissionCents;
99	            $weightedRateSum += ((float) $row->commission_rate) * $commissionCents;
100	            $rateWeight += $commissionCents;
101	            $currency = (string) ($row->currency_code ?? $currency);
102	
103	            $variantId = (string) ($row->shopify_variant_id ?? '');
104	            $variantKey = $variantId !== '' ? $variantId : '__no_variant__';
105	
106	            if (! isset($variants[$variantKey])) {
107	                // Shopify line_item.variant_title is not captured into order_items
108	                // (only line_item.title is mirrored). For variant-aware display the
109	                // line title is the closest stable proxy; pure-product orders show
110	                // the product title, variant orders show whatever Shopify formatted.
111	                $variants[$variantKey] = [
112	                    'variant_id' => $variantId,
113	                    'variant_title' => (string) ($row->title ?? ''),
114	                    'units' => 0,
115	                    'revenue_cents' => 0,
116	                ];
117	            }
118	            $variants[$variantKey]['units'] += $qty;
119	            $variants[$variantKey]['revenue_cents'] += $revenueCents;
120	        }
121	
122	        // Sort variants by revenue desc, drop the synthetic key.
123	        $variantsList = array_values($variants);
124	        usort($variantsList, fn ($a, $b) => $b['revenue_cents'] <=> $a['revenue_cents']);
125	
126	        $recentSales = $rows->take(5)->map(function ($row) {
127	            $occurredAt = $row->occurred_at !== null ? \Illuminate\Support\Carbon::parse($row->occurred_at) : null;
128	
129	            return [
130	                'affiliate_name' => (string) ($row->affiliate_name ?? 'Unknown'),
131	                'quantity' => (int) $row->quantity,
132	                'revenue_cents' => (int) $row->line_total_cents,
133	                'commission_cents' => (int) $row->commission_cents,
134	                'occurred_at' => $occurredAt?->toIso8601String(),
135	            ];
136	        })->values()->all();
137	
138	        $avgRate = $rateWeight > 0 ? $weightedRateSum / $rateWeight : 0.0;
139	
140	        return [
141	            'product_id' => $productId,
142	            'active' => $this->resolveActive($professionalId, $productId),
143	            'currency_code' => $currency,
144	            'period_days' => 30,
145	            'totals' => [
146	                'units' => $totalUnits,
147	                'revenue_cents' => $totalRevenueCents,
148	                'commission_cents' => $totalCommissionCents,
149	                'avg_commission_rate' => round($avgRate, 2),
150	            ],
151	            'variants' => $variantsList,
152	            'recent_sales' => $recentSales,
153	        ];
154	    }
155	
156	    /**
157	     * Look up the sidest.active metafield for this product. Null when the
158	     * metafield isn't set yet (newly synced product).
159	     */
160	    private function resolveActive(string $professionalId, string $productId): ?bool
161	    {
